OUT_OF_SCOPE=$(grep "$TODAY" "$LOG" | grep -v -f "$SCOPE" | wc -l | xargs)
if [ "$OUT_OF_SCOPE" -gt 0 ]; then
  echo "SCOPE ALERT: $OUT_OF_SCOPE logged lines outside signed scope on $TODAY — bill or cut."
else
  echo "Scope clean for $TODAY."
fi
