# lab/evening_watch.py — peak-window guard (alerts before customers feel it)
import statistics

P95_BUDGET_MS = 120

def check(samples: list[float]) -> str:
    s = sorted(samples)
    p95 = s[int(len(s) * 0.95)]
    if p95 > P95_BUDGET_MS:
